void AptLoadScreen::PlayerColor(int index, char *result, bool set)
{
	if (set)
		return;
	if (index >= 8)
		return;
	int slotIndex = m_slotMap[index];
	if (slotIndex < 0 || slotIndex >= 8)
		return;
	_mbscpy((unsigned char *)result, (const unsigned char *)"0");
	if (m_game == 0)
		return;
	GameSlot *slot = m_game->getSlot(slotIndex);
	if (slot == 0)
		return;
	if (!slot->isOccupied())
		return;
	sprintf(result, "%d", TheMultiplayerSettings->getColor(slot->getApparentColor())->m_color);
}

